*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#081729;color:#fff;font-family:'DM Sans',sans-serif}button{font:inherit;color:inherit}#game{position:relative;width:100%;height:100%;min-height:500px;overflow:hidden;background:linear-gradient(180deg,#f6a65e 0%,#ffcc7c 42%,#9dc16b 43%,#4a8f55 100%)}#scene{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(6,18,34,.48),transparent 25%,transparent 68%,rgba(2,17,28,.32)),radial-gradient(ellipse at center,transparent 35%,rgba(2,13,28,.27) 100%)}
.topbar{position:absolute;top:0;left:0;right:0;height:78px;padding:17px 4.1vw;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.13);background:linear-gradient(180deg,rgba(4,17,34,.6),rgba(4,17,34,.08));z-index:3}.brand{display:flex;align-items:center;gap:10px;color:#fff;text-decoration:none;font:800 12px/10px 'Barlow Condensed',sans-serif;letter-spacing:1.6px}.brand b{font-size:15px;letter-spacing:2px}.brand-mark{display:grid;place-items:center;width:34px;height:34px;background:#ffca58;border:2px solid rgba(255,255,255,.7);border-radius:11px 11px 11px 3px;color:#17233a;font:900 24px 'Barlow Condensed';transform:rotate(-8deg);box-shadow:0 4px 16px #f4a74755}.race-label{font-size:10px;letter-spacing:2px;font-weight:800;color:#fff;text-shadow:0 1px 5px #312c3b}.race-label i{font-style:normal;color:#ffc655;padding:0 7px}.live-dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:#76e3a8;margin-right:8px;box-shadow:0 0 0 4px #76e3a833}.sound-btn{border:1px solid #ffffff55;background:#071a304d;padding:9px 13px;border-radius:6px;letter-spacing:1px;font-size:10px;font-weight:800;cursor:pointer}.sound-btn:hover{background:#ffffff22}.sound-btn span{margin-left:5px}
.hud{position:absolute;z-index:2;top:99px;left:4.1vw;display:flex;align-items:flex-start;gap:10px;pointer-events:none}.timer-card,.lap-card,.coin-card{height:74px;padding:12px 17px;background:linear-gradient(135deg,#102944e8,#071a30d9);border:1px solid #ffffff25;border-radius:9px;box-shadow:0 8px 24px #07182b33;position:relative}.timer-card{min-width:122px;border-left:3px solid #ffca58}.eyebrow{display:block;font:800 9px 'DM Sans',sans-serif;letter-spacing:1.9px;color:#a8bed0}.timer-card strong{font:800 29px/.95 'Barlow Condensed',sans-serif;letter-spacing:1px;color:#fff}.timer-unit{font:700 9px 'DM Sans';letter-spacing:1px;color:#a8bed0;margin-left:4px}.timer-card.urgent strong{color:#ff826b}.lap-card{min-width:95px}.lap-card strong{display:block;font:800 23px/.95 'Barlow Condensed';margin-top:5px}.lap-card small{font-size:12px;color:#96aec1}.lap-track{height:3px;background:#ffffff25;margin-top:8px;border-radius:3px;overflow:hidden}.lap-track i{display:block;width:0;height:100%;background:#ffca58;transition:width .15s}.coin-card{display:flex;align-items:center;gap:9px;min-width:95px}.coin-icon{font-size:25px;color:#ffd45b;text-shadow:0 0 12px #ffc542}.coin-card strong{font:800 22px 'Barlow Condensed';display:block;line-height:1}.speed-card{position:absolute;left:calc(100vw - 245px);top:0;width:114px;height:93px;background:linear-gradient(135deg,#102944d9,#071a30cc);border:1px solid #ffffff2a;border-radius:9px;padding:9px 12px;text-align:center}.speedometer{position:relative;height:70px}.speedometer svg{width:88px;height:54px;overflow:visible}.speedometer path{fill:none;stroke:#ffffff35;stroke-width:6;stroke-linecap:round}.speedometer path.speed-fill{stroke:#ffc857;stroke-dasharray:126;stroke-dashoffset:126;transition:stroke-dashoffset .2s,stroke .2s}.speedometer span{position:absolute;top:27px;left:0;right:0;font:800 23px 'Barlow Condensed';letter-spacing:1px}.speedometer small{position:absolute;top:53px;left:0;right:0;font-size:8px;letter-spacing:2px;color:#a8bed0}
.mini-map{position:absolute;top:102px;right:4.1vw;width:180px;height:133px;padding:7px 8px 17px;background:#102944c9;border:1px solid #ffffff31;border-radius:8px;z-index:2}.mini-map canvas{width:100%;height:100%}.map-label{position:absolute;bottom:5px;left:10px;font-size:8px;letter-spacing:1.8px;font-weight:800;color:#a8bed0}.toast{position:absolute;z-index:4;left:50%;top:27%;transform:translate(-50%,-10px);font:800 16px 'Barlow Condensed';letter-spacing:2px;color:#ffe17a;text-shadow:0 2px 8px #111;opacity:0;transition:.3s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.countdown{position:absolute;left:50%;top:45%;transform:translate(-50%,-50%);z-index:4;font:900 clamp(60px,12vw,130px)/.8 'Barlow Condensed';font-style:italic;color:white;text-shadow:0 8px 30px #152b46;pointer-events:none}.countdown.go{color:#ffce61}
.overlay{position:absolute;inset:0;z-index:5;display:flex;align-items:center;padding:80px 10vw 50px;background:linear-gradient(90deg,rgba(5,20,38,.78) 0%,rgba(5,20,38,.48) 43%,rgba(5,20,38,.02) 100%)}.intro-copy{max-width:510px;margin-top:8px}.kicker{font-size:10px;letter-spacing:2.4px;font-weight:800;color:#ffcf63;margin:0 0 14px}.kicker span{font-size:13px;margin-right:5px}.intro h1,.result h2{font:900 clamp(64px,9vw,114px)/.78 'Barlow Condensed',sans-serif;letter-spacing:-2px;margin:0 0 22px;text-shadow:0 5px 25px #10192d55}.intro h1 em,.result h2 em{font-style:italic;color:#ffcc5d}.intro-text{color:#e0e9ed;font-size:14px;line-height:1.65;margin:24px 0 28px}.primary-btn{cursor:pointer;border:0;border-radius:5px;padding:14px 19px;background:#ffca58;color:#1a2939;font-size:11px;font-weight:900;letter-spacing:1.5px;box-shadow:0 7px 20px #f9b84540;transition:transform .18s,background .18s}.primary-btn:hover{transform:translateY(-2px);background:#ffdb7f}.primary-btn span{font-size:18px;margin-left:20px;vertical-align:-2px}.intro-footer{position:absolute;left:10vw;bottom:37px;display:flex;gap:24px;color:#c3d0d5;font-size:9px;letter-spacing:1.5px;font-weight:800}.intro-footer b{color:#ffcd62;font-size:12px}.control-hint{position:absolute;left:10vw;bottom:75px;display:flex;align-items:center;gap:5px;font-size:9px;letter-spacing:1.4px;font-weight:800;color:#d4e0e4}.keycap{display:inline-grid;place-items:center;width:22px;height:23px;border:1px solid #ffffff77;border-bottom-width:2px;border-radius:4px;background:#ffffff17;color:#fff;font-size:10px;font-weight:800}.keycap.wide{width:59px;font-size:9px}.or{margin:0 5px;color:#a7bac7;font-size:9px;text-transform:uppercase}.bottom-hint{position:absolute;z-index:2;bottom:28px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:8px;font-size:9px;letter-spacing:1.2px;font-weight:800;color:#ffffffc9;text-shadow:0 1px 5px #0a1c30}.bottom-hint .keycap{width:48px;height:22px;font-size:8px}.hint-divider{color:#ffc85b;font-size:14px}.credits{position:absolute;z-index:2;bottom:14px;right:4.1vw;font-size:8px;letter-spacing:1.7px;font-weight:800;color:#ffffff9a;text-shadow:0 1px 5px #0a1c30}.credits span{color:#ffce64}.hidden{display:none!important}.result{justify-content:flex-end;background:linear-gradient(90deg,rgba(4,19,36,.12),rgba(4,19,36,.72) 45%,rgba(4,19,36,.88))}.result-panel{width:min(410px,44vw);margin-right:7vw;padding:33px;background:#0a233ce8;border:1px solid #ffffff2a;border-radius:12px;box-shadow:0 20px 70px #05142888}.result h2{font-size:66px;margin-bottom:15px}.result-copy{color:#c7d7de;font-size:13px;margin:0 0 22px}.result-stats{display:flex;gap:26px;margin:0 0 25px}.result-stats div{display:flex;flex-direction:column;gap:4px}.result-stats span{font-size:8px;letter-spacing:1.5px;color:#9eb4c2;font-weight:800}.result-stats b{font:800 22px 'Barlow Condensed';color:#ffcf63}.pause-chip{position:absolute;z-index:6;left:50%;top:50%;transform:translate(-50%,-50%);padding:14px 20px;background:#071a30dd;border:1px solid #ffffff44;border-radius:8px;font:800 13px 'Barlow Condensed';letter-spacing:2px;box-shadow:0 5px 25px #07182b55}.pause-chip span{color:#ffc95b;margin:0 8px}.touch-controls{display:none;position:absolute;z-index:3;inset:auto 0 24px;padding:0 22px;justify-content:space-between;align-items:flex-end;pointer-events:none}.touch-controls button{pointer-events:auto;touch-action:none;border:1px solid #ffffff70;background:#1029449c;backdrop-filter:blur(4px);color:white;box-shadow:0 3px 10px #07182b66}.touch-steer{width:62px;height:62px;border-radius:50%;font:700 38px 'Barlow Condensed'}.touch-pedals{display:flex;gap:10px}.pedal{width:56px;height:58px;border-radius:13px;font-size:18px}.pedal.gas{background:#ffca58c9;color:#14263a}.pedal.brake{opacity:.82}.touch-controls button:active{transform:scale(.94);background:#ffca58;color:#14263a}.intro~.touch-controls{display:none}
@media(max-width:700px){#game{min-height:100dvh}.topbar{height:64px;padding:12px 18px}.race-label{font-size:8px;letter-spacing:1.3px}.sound-btn{padding:8px}.sound-btn span{display:none}.hud{top:77px;left:14px;gap:6px}.timer-card,.lap-card,.coin-card{height:60px;padding:8px 10px;border-radius:7px}.timer-card{min-width:91px}.timer-card strong{font-size:24px}.eyebrow{font-size:7px;letter-spacing:1.2px}.timer-unit{font-size:8px}.lap-card{min-width:70px}.lap-card strong{font-size:20px}.coin-card{min-width:65px;gap:5px}.coin-icon{font-size:18px}.coin-card strong{font-size:18px}.speed-card{display:none}.mini-map{top:77px;right:14px;width:118px;height:91px;padding:5px 5px 15px}.map-label{font-size:6px;bottom:4px;left:7px}.overlay{padding:78px 8vw 60px;background:linear-gradient(90deg,rgba(5,20,38,.82),rgba(5,20,38,.49) 75%,rgba(5,20,38,.2))}.intro-copy{margin-top:50px}.intro h1{font-size:clamp(62px,19vw,93px)}.kicker{font-size:8px;letter-spacing:1.7px}.intro-text{font-size:12px}.intro-footer{left:8vw;bottom:27px;gap:12px;font-size:7px}.intro-footer b{font-size:10px}.control-hint{left:8vw;bottom:60px}.bottom-hint{display:none}.credits{right:12px;bottom:8px;font-size:6px;letter-spacing:1px}.touch-controls{display:flex}.intro~.touch-controls{display:none}.result{justify-content:center;background:#06182ad9;padding:20px}.result-panel{width:min(100%,390px);margin:0;padding:25px}.result h2{font-size:55px}.result-stats{justify-content:space-between}.pause-chip{width:max-content;font-size:11px}.toast{top:29%;font-size:13px}}
@media(min-width:701px) and (max-height:620px){.topbar{height:60px}.hud,.mini-map{top:75px}.intro h1{font-size:78px}.intro-text{margin:15px 0}.intro-footer{bottom:18px}.control-hint{bottom:48px}.bottom-hint{bottom:13px}.credits{bottom:9px}}

import * as THREE from 'three';

const canvas = document.querySelector('#scene');
const mapCanvas = document.querySelector('#map');
const mapCtx = mapCanvas.getContext('2d');
const ui = {
  intro: document.querySelector('#intro'), result: document.querySelector('#result'),
  start: document.querySelector('#startBtn'), again: document.querySelector('#againBtn'),
  timer: document.querySelector('#timer'), lap: document.querySelector('#lap'),
  lapProgress: document.querySelector('#lapProgress'), coins: document.querySelector('#coins'),
  speed: document.querySelector('#speed'), speedArc: document.querySelector('#speedArc'),
  countdown: document.querySelector('#countdown'), toast: document.querySelector('#toast'),
  pause: document.querySelector('#pauseChip'), sound: document.querySelector('#soundBtn'),
  touch: document.querySelector('#touchControls')
};

const scene = new THREE.Scene();
scene.background = new THREE.Color('#f6a96a');
scene.fog = new THREE.Fog('#b9be83', 90, 235);
const camera = new THREE.PerspectiveCamera(57, innerWidth / innerHeight, .1, 450);
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.8));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.18;

scene.add(new THREE.HemisphereLight('#fff0d3', '#567444', 2.25));
const sun = new THREE.DirectionalLight('#fff0c8', 3.2);
sun.position.set(-65, 92, -45); sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
sun.shadow.camera.left = -100; sun.shadow.camera.right = 100;
sun.shadow.camera.top = 100; sun.shadow.camera.bottom = -100;
sun.shadow.bias = -.0004;
scene.add(sun);
const fill = new THREE.DirectionalLight('#91baff', .65); fill.position.set(45, 28, 62); scene.add(fill);

const mat = (color, roughness=.8, extra={}) => new THREE.MeshStandardMaterial({ color, roughness, ...extra });
const grassMat = mat('#659451');
const darkGrassMat = mat('#4c804d');
const asphaltMat = mat('#4b5155', .92);
const curbRed = mat('#ed6550');
const curbCream = mat('#f4e9cd');
const laneMat = mat('#f7d88e', .7, { emissive: '#5e4523', emissiveIntensity: .12 });
const goldMat = new THREE.MeshStandardMaterial({ color: '#ffc83d', metalness: .7, roughness: .22, emissive: '#b4780d', emissiveIntensity: .38 });
const track = { rx: 42, rz: 27, width: 12, samples: 256 };
const world = new THREE.Group(); scene.add(world);
const ground = new THREE.Mesh(new THREE.PlaneGeometry(500, 500), grassMat);
ground.rotation.x = -Math.PI / 2; ground.position.y = -.16; ground.receiveShadow = true; world.add(ground);

function pointOnTrack(t, offset=0) {
  const x = track.rx * Math.cos(t), z = track.rz * Math.sin(t);
  const dx = -track.rx * Math.sin(t), dz = track.rz * Math.cos(t);
  const len = Math.hypot(dx, dz);
  const nx = dz / len, nz = -dx / len;
  return new THREE.Vector3(x + nx * offset, 0, z + nz * offset);
}
function makeStrip(inner, outer, material, y=.01, segments=track.samples) {
  const positions = [], indices = [];
  for (let i=0;i<=segments;i++) {
    const t=i/segments*Math.PI*2;
    const a=pointOnTrack(t,inner), b=pointOnTrack(t,outer);
    positions.push(a.x,y,a.z,b.x,y,b.z);
    if(i<segments){const n=i*2;indices.push(n,n+1,n+2,n+1,n+3,n+2);}
  }
  const geo=new THREE.BufferGeometry(); geo.setAttribute('position',new THREE.Float32BufferAttribute(positions,3)); geo.setIndex(indices); geo.computeVertexNormals();
  const mesh=new THREE.Mesh(geo,material); mesh.receiveShadow=true; world.add(mesh); return mesh;
}
makeStrip(-track.width/2, track.width/2, asphaltMat, -.015);
makeStrip(-track.width/2-1.6,-track.width/2,curbRed,.005);
makeStrip(track.width/2,track.width/2+1.6,curbRed,.005);
// Alternating curb blocks, lane dashes, and the soft inner shoulder.
for(let i=0;i<track.samples;i+=4){
  const t=i/track.samples*Math.PI*2;
  for(const side of [-1,1]){
    const p=pointOnTrack(t,side*(track.width/2+.8));
    const curb=new THREE.Mesh(new THREE.BoxGeometry(1.05,.14,1.05),i%8===0?curbCream:curbRed);
    curb.position.set(p.x,.075,p.z); curb.rotation.y=-t; curb.receiveShadow=true; curb.castShadow=true; world.add(curb);
  }
}
const dashGeo=new THREE.BoxGeometry(1.5,.025,.13);
for(let i=0;i<64;i++){
  const t=i/64*Math.PI*2, p=pointOnTrack(t,0);
  const dash=new THREE.Mesh(dashGeo,laneMat); dash.position.set(p.x,.015,p.z);
  dash.rotation.y=Math.atan2(track.rx*Math.sin(t),track.rz*Math.cos(t)); world.add(dash);
}

// A wide, soft-edged oval shadow and warm sun in the horizon.
const sunDisc=new THREE.Mesh(new THREE.SphereGeometry(12,32,24),new THREE.MeshBasicMaterial({color:'#ffdf9a'}));
sunDisc.position.set(-105,52,-175); scene.add(sunDisc);
const sunGlow=new THREE.PointLight('#ffd18c',160,260,2);sunGlow.position.copy(sunDisc.position);scene.add(sunGlow);

function addTree(x,z,scale=1){
  const g=new THREE.Group();g.position.set(x,0,z);g.scale.setScalar(scale);
  const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.28,.44,3.8,7),mat('#76563a'));trunk.position.y=1.9;trunk.castShadow=true;g.add(trunk);
  const colors=['#2f694c','#39764f','#558958'];
  for(let i=0;i<3;i++){const crown=new THREE.Mesh(new THREE.IcosahedronGeometry(2.5-i*.32,1),mat(colors[(i+Math.floor(x+z))%3]));crown.position.set((i%2-.5)*.8,4.2+i*1.35,(i-1)*.35);crown.scale.set(1.1,.95,1);crown.castShadow=true;g.add(crown);}
  world.add(g);
}
for(let i=0;i<58;i++){
  const t=i/58*Math.PI*2, side=i%2?1:-1;
  const p=pointOnTrack(t,side*(track.width/2+8+(i%4)*2)); addTree(p.x,p.z,.72+(i%5)*.12);
}
// Tiny flower patches give the infield a little color without cluttering the racing line.
for(let i=0;i<90;i++){
  const x=(Math.random()-.5)*68,z=(Math.random()-.5)*42;
  const norm=(x*x)/(track.rx*track.rx)+(z*z)/(track.rz*track.rz);
  if(norm<.65||norm>2.2)continue;
  const flower=new THREE.Mesh(new THREE.SphereGeometry(.12,6,5),mat(i%3?'#fff0c0':'#f1a0a2'));
  flower.position.set(x,.12,z);world.add(flower);
}

function addBillboard(t, side, title, color){
  const p=pointOnTrack(t,side*(track.width/2+6));
  const postMat=mat('#624c38');
  const post=new THREE.Mesh(new THREE.BoxGeometry(.24,3.6,.24),postMat);post.position.set(p.x,1.8,p.z);post.castShadow=true;world.add(post);
  const board=new THREE.Group();board.position.set(p.x,3.3,p.z);board.rotation.y=-t+Math.PI/2;
  const face=new THREE.Mesh(new THREE.BoxGeometry(7,2.1,.22),mat(color,.55,{emissive:color,emissiveIntensity:.13}));face.castShadow=true;board.add(face);
  const stripe=new THREE.Mesh(new THREE.BoxGeometry(7.05,.16,.24),mat('#ffe5a0'));stripe.position.y=-.83;board.add(stripe);
  const signCanvas=document.createElement('canvas');signCanvas.width=512;signCanvas.height=128;
  const ctx=signCanvas.getContext('2d');ctx.fillStyle=color;ctx.fillRect(0,0,512,128);
  ctx.fillStyle='#fff4d8';ctx.font='900 62px Arial';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(title,256,61);
  const texture=new THREE.CanvasTexture(signCanvas);texture.colorSpace=THREE.SRGBColorSpace;
  const text=new THREE.Mesh(new THREE.PlaneGeometry(6.7,1.65),new THREE.MeshBasicMaterial({map:texture,transparent:false}));text.position.z=.13;board.add(text);world.add(board);
}
addBillboard(.55,1,'SUNSET SPRINT','#b7443f');addBillboard(2.9,-1,'GO! GO!','#397c68');addBillboard(4.65,1,'TURBO!','#b97827');

// Start/finish gantry and checkered stripe.
const startPoint=pointOnTrack(-Math.PI/2,0);
const startYaw=Math.PI/2;
const gantry=new THREE.Group();gantry.position.set(startPoint.x,0,startPoint.z);gantry.rotation.y=startYaw;world.add(gantry);
for(const x of [-7,7]){const pole=new THREE.Mesh(new THREE.BoxGeometry(.48,6,.48),mat('#f3e7d0'));pole.position.set(x,3,0);pole.castShadow=true;gantry.add(pole);}
const beam=new THREE.Mesh(new THREE.BoxGeometry(15,.75,.7),mat('#f3e7d0'));beam.position.y=6;gantry.add(beam);
for(let x=-7.2;x<7.2;x+=1.2){for(let y=5.1;y<6.9;y+=.9){const tile=new THREE.Mesh(new THREE.BoxGeometry(1.2,.9,.72),mat((Math.round((x+7.2)/1.2)+Math.round((y-5.1)/.9))%2?'#273244':'#fff0d2'));tile.position.set(x,y,0);gantry.add(tile);}}

// Kart: original little racer with a bright shell, rounded nose and chunky rubber tires.
const kart=new THREE.Group();scene.add(kart);
const chassis=new THREE.Group();kart.add(chassis);
const kartRed=mat('#ef584b',.4,{metalness:.08});const dark=mat('#202933',.72);const rubber=mat('#191e24',.86);const trim=mat('#f4d15d',.38,{metalness:.2});
const lower=new THREE.Mesh(new THREE.BoxGeometry(1.65,.42,2.45),dark);lower.position.y=.48;lower.castShadow=true;chassis.add(lower);
const body=new THREE.Mesh(new THREE.BoxGeometry(1.82,.62,1.78),kartRed);body.position.set(0,.84,-.05);body.castShadow=true;chassis.add(body);
const nose=new THREE.Mesh(new THREE.BoxGeometry(1.48,.33,.72),mat('#ff7860',.38));nose.position.set(0,.79,-1.15);nose.castShadow=true;chassis.add(nose);
const bumper=new THREE.Mesh(new THREE.BoxGeometry(1.95,.19,.26),trim);bumper.position.set(0,.5,-1.46);chassis.add(bumper);
const seat=new THREE.Mesh(new THREE.BoxGeometry(.82,.55,.72),mat('#273a4b'));seat.position.set(0,1.28,.3);seat.castShadow=true;chassis.add(seat);
const driver=new THREE.Mesh(new THREE.SphereGeometry(.43,16,12),mat('#f4bc8b'));
driver.position.set(0,1.74,.22);driver.scale.set(.9,1.08,.88);driver.castShadow=true;chassis.add(driver);
const helmet=new THREE.Mesh(new THREE.SphereGeometry(.53,18,14),mat('#ffce58',.35));helmet.position.set(0,2.02,.16);helmet.scale.set(1.05,.9,.98);helmet.castShadow=true;chassis.add(helmet);
const visor=new THREE.Mesh(new THREE.BoxGeometry(.69,.2,.1),mat('#243b50',.26,{metalness:.25}));visor.position.set(0,1.99,-.31);chassis.add(visor);
const scarf=new THREE.Mesh(new THREE.BoxGeometry(.88,.16,.24),mat('#fff0d2'));scarf.position.set(0,1.44,.05);chassis.add(scarf);
const wheels=[];
for(const x of [-.98,.98])for(const z of [-.92,.88]){
  const wheel=new THREE.Mesh(new THREE.CylinderGeometry(.39,.39,.29,16),rubber);wheel.rotation.z=Math.PI/2;wheel.position.set(x,.45,z);wheel.castShadow=true;chassis.add(wheel);wheels.push(wheel);
  const hub=new THREE.Mesh(new THREE.CylinderGeometry(.19,.19,.3,12),trim);hub.rotation.z=Math.PI/2;hub.position.copy(wheel.position);chassis.add(hub);
}
