const exhausts=[];
for(const x of [-.55,.55]){const e=new THREE.Mesh(new THREE.CylinderGeometry(.12,.16,.3,10),mat('#68737a',.4,{metalness:.55}));e.rotation.x=Math.PI/2;e.position.set(x,.45,1.28);chassis.add(e);const flame=new THREE.Mesh(new THREE.ConeGeometry(.15,.55,10),new THREE.MeshBasicMaterial({color:'#ff9c4a',transparent:true,opacity:.8}));flame.rotation.x=-Math.PI/2;flame.position.set(x,.45,1.65);flame.visible=false;chassis.add(flame);exhausts.push(flame);}

function makePickup(t,offset=0){
  const group=new THREE.Group();const p=pointOnTrack(t,offset);group.position.set(p.x,1.25,p.z);
  const coin=new THREE.Mesh(new THREE.TorusGeometry(.56,.13,10,22),goldMat);coin.castShadow=true;group.add(coin);
  const inner=new THREE.Mesh(new THREE.CylinderGeometry(.35,.35,.1,18),goldMat);inner.rotation.x=Math.PI/2;group.add(inner);
  const sparkle=new THREE.PointLight('#ffd762',1.8,4);sparkle.position.y=.25;group.add(sparkle);
  world.add(group);return {group,t,offset,active:true,baseY:1.25};
}
const pickups=[];
for(let i=0;i<18;i++)pickups.push(makePickup(i/18*Math.PI*2,[-2.2,0,2.2][i%3]));
const boosts=[];
for(const t of [.38,1.52,2.68,3.83,5.02]){
  const p=pointOnTrack(t,0);const pad=new THREE.Group();pad.position.set(p.x,.06,p.z);pad.rotation.y=-t+Math.PI/2;
  const plate=new THREE.Mesh(new THREE.BoxGeometry(4.2,.12,2.1),mat('#31cfbd',.38,{emissive:'#00b8a6',emissiveIntensity:.65}));plate.castShadow=true;pad.add(plate);
  for(let i=-1;i<=1;i++){const arrow=new THREE.Mesh(new THREE.ConeGeometry(.28,.7,3),mat('#e4fff0',.4,{emissive:'#baffeb',emissiveIntensity:.4}));arrow.rotation.x=-Math.PI/2;arrow.position.set(i*1.1,.13,-.05);pad.add(arrow);}
