function nearestRoute(x,z){let best=Infinity,index=0;for(let i=0;i<route.length;i++){const p=route[i].p,d=(p.x-x)**2+(p.z-z)**2;if(d<best){best=d;index=i;}}return {index,distance:Math.sqrt(best)};}
function wrap(n,max){return ((n%max)+max)%max;}
function normAngle(a){return Math.atan2(Math.sin(a),Math.cos(a));}
const state={mode:'intro',time:60,speed:0,coins:0,lap:0,bestLap:Infinity,lapStarted:0,progress:0,lastProgress:0,routeIndex:0,offroad:0,boost:0,boostCooldown:0,shake:0,frame:0};
let keys=new Set(),lastTick=performance.now(),countInterval=null,toastTimeout=null;
const sound={enabled:true,ctx:null};
function beep(freq=440,duration=.08,type='sine',volume=.035){if(!sound.enabled)return;try{sound.ctx??=new AudioContext();if(sound.ctx.state==='suspended')sound.ctx.resume();const osc=sound.ctx.createOscillator(),gain=sound.ctx.createGain();osc.type=type;osc.frequency.value=freq;gain.gain.setValueAtTime(volume,sound.ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,sound.ctx.currentTime+duration);osc.connect(gain);gain.connect(sound.ctx.destination);osc.start();osc.stop(sound.ctx.currentTime+duration);}catch{}}
function showToast(text){ui.toast.textContent=text;ui.toast.classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>ui.toast.classList.remove('show'),1050);}
function pointKart(){return pointOnTrack(state.progress/routeLength*Math.PI*2,0);}
function setKartStart(){const p=pointOnTrack(-Math.PI/2,0);kart.position.set(p.x,0,p.z);kart.rotation.y=startYaw;state.progress=0;state.lastProgress=0;state.routeIndex=0;}
setKartStart();
function drawMap(){
  const w=mapCanvas.width,h=mapCanvas.height;mapCtx.clearRect(0,0,w,h);
  mapCtx.fillStyle='rgba(7,21,36,.12)';mapCtx.fillRect(0,0,w,h);
  const sx=1.42,sz=1.43,cx=w/2,cy=h/2+2;
  mapCtx.beginPath();mapCtx.ellipse(cx,cy,track.rx*sx,track.rz*sz,0,0,Math.PI*2);mapCtx.strokeStyle='rgba(226,237,226,.38)';mapCtx.lineWidth=13;mapCtx.stroke();
  mapCtx.beginPath();mapCtx.ellipse(cx,cy,track.rx*sx,track.rz*sz,0,0,Math.PI*2);mapCtx.strokeStyle='#59666a';mapCtx.lineWidth=9;mapCtx.stroke();
  mapCtx.beginPath();mapCtx.ellipse(cx,cy,track.rx*sx,track.rz*sz,0,0,Math.PI*2);mapCtx.strokeStyle='#e3d6af';mapCtx.lineWidth=1.3;mapCtx.setLineDash([6,8]);mapCtx.stroke();mapCtx.setLineDash([]);
