}
function startRun(){
  clearInterval(countInterval);keys.clear();state.mode='countdown';state.time=60;state.speed=0;state.coins=0;state.lap=0;state.bestLap=Infinity;state.lapStarted=0;state.offroad=0;state.boost=0;state.boostCooldown=0;
  pickups.forEach(p=>{p.active=true;p.group.visible=true;});boosts.forEach(b=>b.active=true);
  ui.intro.classList.add('hidden');ui.result.classList.add('hidden');ui.pause.classList.add('hidden');ui.touch.classList.remove('hidden');ui.countdown.textContent='3';ui.countdown.classList.remove('go');setKartStart();
  let n=3;countInterval=setInterval(()=>{n--;if(n>0){ui.countdown.textContent=String(n);beep(540,.07,'sine',.04);}else if(n===0){ui.countdown.textContent='GO!';ui.countdown.classList.add('go');beep(780,.2,'triangle',.055);}else{clearInterval(countInterval);ui.countdown.textContent='';state.mode='playing';state.lapStarted=performance.now();}},760);
  beep(390,.1,'sine');updateHud();
}
function endRun(reason='time'){
  if(state.mode==='result')return;state.mode='result';keys.clear();
  const laps=state.lap;
  if(reason==='finish'){
    document.querySelector('#resultKicker').textContent='CIRCUIT COMPLETE';document.querySelector('#resultTitle').innerHTML='SUNSET<br><em>CHAMPION.</em>';document.querySelector('#resultCopy').textContent='Three laps, one golden-hour legend. Beautifully driven.';
  }else if(reason==='crash'){
    document.querySelector('#resultKicker').textContent='OUT OF TIME';document.querySelector('#resultTitle').innerHTML='NICE<br><em>DRIVING.</em>';document.querySelector('#resultCopy').textContent='The sunset won this round. Your next lap starts now.';
  }else{
    document.querySelector('#resultKicker').textContent='TIME’S UP';document.querySelector('#resultTitle').innerHTML=laps?'NICE<br><em>DRIVING.</em>':'THE ROAD<br><em>AWaits.</em>'.toUpperCase();document.querySelector('#resultCopy').textContent=laps?'The track is yours. Take another lap?':'Every great racer starts somewhere. Fancy a rematch?';
  }
  document.querySelector('#resultLaps').textContent=String(laps);document.querySelector('#resultCoins').textContent=String(state.coins);document.querySelector('#resultBest').textContent=Number.isFinite(state.bestLap)?`${state.bestLap.toFixed(1)}s`:'—';
  ui.result.classList.remove('hidden');ui.touch.classList.add('hidden');ui.pause.classList.add('hidden');ui.countdown.textContent='';beep(350,.3,'triangle',.045);
}
function togglePause(){if(state.mode==='playing'){state.mode='paused';keys.clear();ui.pause.classList.remove('hidden');}else if(state.mode==='paused'){state.mode='playing';ui.pause.classList.add('hidden');lastTick=performance.now();}}
function keyDown(e){const key=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(key))e.preventDefault();if(key===' '){if(!e.repeat)togglePause();return;}if(key==='r'){startRun();return;}keys.add(key);}
function keyUp(e){keys.delete(e.key.toLowerCase());}
window.addEventListener('keydown',keyDown,{passive:false});window.addEventListener('keyup',keyUp);
window.addEventListener('blur',()=>{keys.clear();if(state.mode==='playing')togglePause();});
ui.start.addEventListener('click',startRun);ui.again.addEventListener('click',startRun);
ui.sound.addEventListener('click',()=>{sound.enabled=!sound.enabled;ui.sound.innerHTML=sound.enabled?'♪ <span>SOUND ON</span>':'♫ <span>SOUND OFF</span>';if(sound.enabled)beep(620,.08);});
for(const button of document.querySelectorAll('.touch-controls button')){
  const k=button.dataset.key.toLowerCase();
  button.addEventListener('pointerdown',e=>{e.preventDefault();button.setPointerCapture(e.pointerId);keys.add(k);});
