function doMovement(dt){
  if(state.mode!=='playing')return;
  state.time-=dt;if(state.time<=0){state.time=0;updateHud();endRun('time');return;}
  const up=keys.has('w')||keys.has('arrowup'),down=keys.has('s')||keys.has('arrowdown');
  const left=keys.has('a')||keys.has('arrowleft'),right=keys.has('d')||keys.has('arrowright');
  const accel=up?18:0,brake=down?23:0;
  state.speed=THREE.MathUtils.clamp(state.speed+(accel-brake-(up||down?0:4.7))*dt,0,27+(state.boost>0?7:0));
