  const turn=(left?1:0)-(right?1:0);
  const steerPower=(.55+state.speed/27*.75);
  kart.rotation.y+=turn*steerPower*dt*(state.speed>.8?1:.5);
  const drift=keys.has('shift');const targetLean=-turn*(drift?.16:.09)*Math.min(1,state.speed/14);
  chassis.rotation.z=THREE.MathUtils.damp(chassis.rotation.z,targetLean,6,dt);
  const velocity=forward.multiplyScalar(state.speed*dt);
