    if(state.lap>=3){endRun('finish');return;}
  }
  const posAngle=t;
  for(const pickup of pickups){if(!pickup.active)continue;const d=kart.position.distanceTo(pickup.group.position);if(d<2.1){pickup.active=false;pickup.group.visible=false;state.coins++;state.speed=Math.min(31,state.speed+1.4);showToast('COIN +1');beep(940,.07,'sine',.04);}}
  for(const pad of boosts){if(!pad.active)continue;const d=kart.position.distanceTo(pad.pad.position);if(d<2.7&&state.boostCooldown<=0){pad.active=false;state.boost=1.35;state.boostCooldown=2.2;state.speed=Math.min(34,state.speed+7);showToast('TURBO BOOST!');beep(230,.18,'sawtooth',.035);}}
