  if(state.boost>0){state.speed=Math.min(34,state.speed+3.4*dt);}
  const wheelSpin=state.speed*dt*1.25;for(const wheel of wheels)wheel.rotation.x+=wheelSpin;
  exhausts.forEach(e=>{e.visible=state.boost>0;e.scale.setScalar(.8+Math.random()*.6);});
  updateHud();
}

const cameraTarget=new THREE.Vector3(),cameraPos=new THREE.Vector3();
function updateCamera(dt){
  const forward=new THREE.Vector3(-Math.sin(kart.rotation.y),0,-Math.cos(kart.rotation.y));
  const speedFactor=THREE.MathUtils.clamp(state.speed/24,0,1);
  const distance=8.5+speedFactor*2.7;
